#!/usr/bin/env python3
"""Real Chromium DOM interaction regression suite for the self-contained workstation.
The environment blocks browser navigation, so set_content is used. Workspace reload,
command persistence and uncertain saves use the real WorkspaceSession with the local
memory fallback; a separate SQLite suite covers production request persistence.
"""
from pathlib import Path
import os,sys,json,zipfile,io
from playwright.sync_api import sync_playwright,expect
HTML=Path(sys.argv[1]).read_text();OUT=Path(sys.argv[2]);OUT.mkdir(parents=True,exist_ok=True)
checks=[]
def check(v,label):
    assert v,label
    checks.append(label)
    print('PASS',len(checks),label,flush=True)
def setup(browser,width=1600,height=1050):
    page=browser.new_page(viewport={'width':width,'height':height},accept_downloads=True)
    page.set_default_timeout(5000);errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
    page.set_content(HTML,wait_until='load');page.wait_for_function('!!window.ledgerlabPreview');page.evaluate('ledgerlabPreview.session.save({type:"startCareer",seed:271828,startMonth:"2025-07",role:"financial-manager",scenario:"messy",daily:false,confirmation:"START TAKEOVER"})');return page,errors
def win(page):
    id=page.locator('.pc-window[data-active=true]').get_attribute('data-window');return page.locator(f'.pc-window[data-window="{id}"]')
def focus(page,id):page.locator(f'.pc-taskbar [data-task="{id}"]').click()
def goto(w,ref):w.get_by_label('Name box',exact=True).fill(ref);w.get_by_label('Name box',exact=True).press('Enter')
def cell(w,ref):return w.locator(f'td[aria-label="{ref}"] .xl-cell-value')
def enter(w,ref,value):goto(w,ref);w.locator('.xl-grid-scroll').press('F2');w.locator('.xl-cell-editor').fill(value);w.locator('.xl-cell-editor').press('Enter')
def raw(w,ref):goto(w,ref);return w.get_by_label('Formula bar',exact=True).input_value()
def paste(w,text):w.locator('.xl-grid-scroll').evaluate('(el,text)=>{const d=new DataTransfer();d.setData("text/plain",text);el.dispatchEvent(new ClipboardEvent("paste",{bubbles:true,cancelable:true,clipboardData:d}));}',text)
def save(w):w.locator('[data-action=save]').click();expect(w.locator('.pc-editor-status')).to_contain_text('Saved with this case')
def close(w):w.locator('[data-window-action=close]').click()
def workbook(page):
    page.locator('.pc-taskbar [data-action=drive]').click();page.locator('[data-window=explorer] [data-action=new-workbook]').click();w=win(page);w.locator('[data-window-action=max]').click();return w,w.get_attribute('data-window')
def action(w,name):w.locator(f'[data-xl="{name}"]').click()
def ribbon(w,name):w.locator(f'[data-ribbon="{name}"]').click()
