    check(w.locator('.xl-grid-scroll').get_attribute('aria-rowcount')=='100','New workbook opens with 100 rows')
    w.locator('[data-action=file-details]').click();w.get_by_label('Working file name').fill('July control test.xlsx');w.locator('[data-action=file-details]').click()
    goto(w,'B6');w.locator('.xl-grid-scroll').press('1');w.locator('.xl-cell-editor').press('2');w.locator('.xl-cell-editor').press('5');w.locator('.xl-cell-editor').press('Enter')
