    goto(w,'B8');action(w,'copy');goto(w,'E9');action(w,'paste-values')
    check(raw(w,'E9')=='149.75','Paste values stores result, not formula')
    goto(w,'B12');paste(w,'1\t2\n3\t4')
    check(cell(w,'C13').inner_text()=='4','Multiline TSV paste fills a rectangular range')
    goto(w,'B12:C13');w.locator('.xl-grid-scroll').press('Delete')
    check(cell(w,'C13').inner_text()=='','Delete clears the entire selected range')
    w.locator('.xl-grid-scroll').press('Control+z');check(cell(w,'C13').inner_text()=='4','Undo restores a whole rectangular edit')
    w.locator('.xl-grid-scroll').press('Control+y');check(cell(w,'C13').inner_text()=='','Redo reapplies the same rectangular edit')
    goto(w,'B6');w.locator('.xl-grid-scroll').press('Control+b');check(w.locator('td[aria-label=B6]').evaluate('(el)=>getComputedStyle(el).fontWeight')=='700','Ctrl+B formats the selected cell')
    w.get_by_label('Number format',exact=True).select_option('accounting');check(cell(w,'B6').inner_text()=='125.00','Accounting number format applies')
    w.get_by_label('Cell fill',exact=True).fill('#fff2cc');w.get_by_label('Cell fill',exact=True).dispatch_event('change');check('255, 242, 204' in w.locator('td[aria-label=B6]').evaluate('(el)=>getComputedStyle(el).backgroundColor'),'Cell fill applies to grid')
    enter(w,'E12','12.5%');check(cell(w,'E12').inner_text()=='12.50%','Percentage entry infers percentage formatting')
