    action(w,'freeze-col');check(w.locator('td[aria-label=A20]').evaluate('(el)=>getComputedStyle(el).position')=='sticky','Freeze first column pins column A')
    action(w,'unfreeze');check(w.locator('td[aria-label=A20]').evaluate('(el)=>getComputedStyle(el).position')!='sticky','Unfreeze removes frozen panes')
