    action(w,'filter');w.get_by_label('Filter rows',exact=True).fill('Alpha');check(w.locator('td[aria-label=A32]').is_hidden(),'Filter hides nonmatching rows without deleting data');action(w,'clear-filter');check(w.locator('td[aria-label=A32]').is_visible(),'Clear filter restores rows')
    goto(w,'A31');action(w,'insert-row');check(cell(w,'A32').inner_text()=='Alpha','Insert row shifts existing data down');action(w,'delete-row');check(cell(w,'A31').inner_text()=='Alpha','Delete row restores data position')
    ribbon(w,'home');action(w,'find');w.get_by_label('Find in sheet').fill('Zulu');action(w,'find-next');check(w.get_by_label('Name box').input_value()=='A33','Find locates a matching cell');w.get_by_label('Replace with').fill('Gamma');action(w,'replace');check(cell(w,'A33').inner_text()=='Gamma','Replace changes the selected match');action(w,'close-find')
    goto(w,'B6');save(w);check(page.evaluate('(id)=>ledgerlabPreview.model().state.desktop.files.find(f=>f.id===id).sheets.length',sid)==2,'Save persists a multi-sheet workbook through the session command')
