    enter(w,'B6','777');page.locator(f'[data-close-task="{sid}"]').click();page.get_by_role('dialog').get_by_role('button',name='Cancel',exact=True).click();check(w.is_visible() and cell(w,'B6').inner_text()=='777.00','Taskbar × Cancel keeps the unsaved draft')
