    chooser.value.set_files(exported);page.wait_for_function("!!document.querySelector('.pc-window[data-active=true] .xl-workbook')");w=win(page);expect(w.locator('.xl-sheet-tabs [data-sheet]')).to_have_count(2)
    check(cell(w,'B6').inner_text()=='250.00','XLSX import restores numeric cells and number format');check(cell(w,'F6').inner_text()=='300','XLSX import restores cross-sheet calculations')
