    exp.get_by_label('Search finance drive').fill('');page.locator('.pc-taskbar [data-action=mail]').click();mail=page.locator('[data-window=mail]');mail.get_by_label('Search scenario emails').fill('July 2025: Monthly bank statement');mail.locator('[data-mail]').click();mid=mail.locator('[data-mail]').get_attribute('data-mail');mail.locator('[data-action=read]').click();check(page.evaluate('(id)=>ledgerlabPreview.model().state.desktop.readMail.includes(id)',mid),'Scenario mail read status is saved')
