    jid=page.evaluate('ledgerlabPreview.model().state.journals[0].id');app.get_by_label('Accounting workspace',exact=True).select_option('bank');app.locator(f'[name="bank-{bank["id"]}"]').select_option(jid);app.locator(f'[data-local=match][data-id="{bank["id"]}"]').click();page.wait_for_function('(id)=>!!ledgerlabPreview.model().state.bankMatches[id]',arg=bank['id']);check(page.evaluate('(id)=>ledgerlabPreview.model().state.bankMatches[id]',bank['id'])==[jid],'Bank Match selected persists the selected journal IDs')
